import { expect, expectStatus, test, type APIRequestContext } from "../../fixtures";

const KINDS = ["w9", "insurance_certificate", "contract"] as const;
const EXTRACTION_TIMEOUT_MS = 60_000;
const POLL_INTERVAL_MS = 500;

function uniqueSuffix(): string {
  return `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

async function waitForExtracted(member: APIRequestContext, documentId: string): Promise<void> {
  const deadline = Date.now() + EXTRACTION_TIMEOUT_MS;
  let status = "processing";
  while (Date.now() < deadline) {
    const body = await expectStatus<{ status: string }>(await member.get(`/api/documents/${documentId}`), 200);
    status = body.status;
    if (status === "extracted" || status === "failed") break;
    await new Promise((resolve) => setTimeout(resolve, POLL_INTERVAL_MS));
  }
  expect(status).toBe("extracted");
}

test.describe("review vendors", () => {
  test("submitting a vendor with all documents extracted moves it to in_review", { tag: "@REV-01" }, async ({ apiAs }) => {
    // Arrange: a draft vendor with a unique name.
    const member = await apiAs("member");
    const suffix = uniqueSuffix();
    const vendor = await expectStatus<{ id: string; status: string }>(
      await member.post("/api/vendors", {
        data: {
          name: `REV01 Vendor ${suffix}`,
          category: "services",
          contact_email: `rev01-${suffix}@example.test`,
        },
      }),
      201,
    );
    expect(vendor.status).toBe("draft");

    // Arrange: upload one document of each kind and wait for extraction.
    const documents = [];
    for (const kind of KINDS) {
      const document = await expectStatus<{ id: string }>(
        await member.post(`/api/vendors/${vendor.id}/documents`, {
          multipart: {
            kind,
            file: {
              name: `${kind}-${suffix}.pdf`,
              mimeType: "application/pdf",
              buffer: Buffer.from(`%PDF-1.4\n% REV-01 ${kind} ${suffix}\n%%EOF\n`),
            },
          },
        }),
        201,
      );
      documents.push(document);
    }
    for (const document of documents) {
      await waitForExtracted(member, document.id);
    }

    // Act
    const response = await member.post(`/api/vendors/${vendor.id}/submit`);

    // Assert
    const body = await expectStatus<{ id: string; status: string }>(response, 200);
    expect(body.id).toBe(vendor.id);
    expect(body.status).toBe("in_review");
  });

  test("submitting a vendor records a vendor.submitted audit event", { tag: "@REV-01" }, async ({ apiAs }) => {
    // Arrange: a draft vendor with all three documents extracted.
    const member = await apiAs("member");
    const suffix = uniqueSuffix();
    const vendor = await expectStatus<{ id: string }>(
      await member.post("/api/vendors", {
        data: {
          name: `REV01 Audit ${suffix}`,
          category: "hardware",
          contact_email: `rev01-audit-${suffix}@example.test`,
        },
      }),
      201,
    );
    const documents = [];
    for (const kind of KINDS) {
      const document = await expectStatus<{ id: string }>(
        await member.post(`/api/vendors/${vendor.id}/documents`, {
          multipart: {
            kind,
            file: {
              name: `${kind}-${suffix}.pdf`,
              mimeType: "application/pdf",
              buffer: Buffer.from(`%PDF-1.4\n% REV-01 audit ${kind} ${suffix}\n%%EOF\n`),
            },
          },
        }),
        201,
      );
      documents.push(document);
    }
    for (const document of documents) {
      await waitForExtracted(member, document.id);
    }
    await expectStatus(await member.post(`/api/vendors/${vendor.id}/submit`), 200);

    // Act
    const trail = await expectStatus<{ items: { action: string; actor: { email: string } }[] }>(
      await member.get(`/api/vendors/${vendor.id}/audit`),
      200,
    );

    // Assert
    const submitted = trail.items.filter((event) => event.action === "vendor.submitted");
    expect(submitted.length).toBeGreaterThanOrEqual(1);
  });
});
